import{_ as i,o as n,c as t,ah as r}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse(`{"title":"Recherche-Update: Die Thomas Schmid Chats & René Benko","description":"Wir analysieren die Originalzitate der Macht. Über 'Huren für die Reichen' und 600.000-Euro-Jobangebote.","frontmatter":{"title":"Recherche-Update: Die Thomas Schmid Chats & René Benko","description":"Wir analysieren die Originalzitate der Macht. Über 'Huren für die Reichen' und 600.000-Euro-Jobangebote.","date":"2026-02-28T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-28-schmid-chats-recherche.md","filePath":"logbuch/2026-02-28-schmid-chats-recherche.md"}`),s={name:"logbuch/2026-02-28-schmid-chats-recherche.md"};function a(h,e,o,d,c,m){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="recherche-update-die-thomas-schmid-chats-rene-benko" tabindex="-1">Recherche-Update: Die Thomas Schmid Chats &amp; René Benko <a class="header-anchor" href="#recherche-update-die-thomas-schmid-chats-rene-benko" aria-label="Permalink to &quot;Recherche-Update: Die Thomas Schmid Chats &amp; René Benko&quot;">​</a></h1><p>Die heutige Recherche in den <strong>Thomas Schmid Chats</strong> liefert uns die authentischen O-Töne, die unser Drehbuch bisher vermissen ließ. Es ist fast unmöglich, diese Realität satirisch noch zu übertreffen.</p><p><strong>Unsere Highlights aus den Protokollen:</strong></p><ul><li><strong>Das &#39;Hure&#39;-Zitat:</strong> Ein unfassbar ehrlicher Moment der Selbstreflexion eines Spitzenbeamten. Es wird zum zentralen Motiv in einer neuen Szene zwischen Schmid und Benko.</li><li><strong>Der 600.000-Euro-Job:</strong> Wir inszenieren dieses Jobangebot als eine Art „modernen Adelsschlag“ – die endgültige Aufnahme des Beamten in den Pointillismus des Geldes.</li><li><strong>Die HBK-Abstimmung:</strong> Die Bestätigung, dass alle Wege im Finanzministerium am Ende zu „HBK“ (Kurz) führten.</li></ul><p>Diese Chats geben dem „Horten-Mysterium“ eine beklemmende Modernität. Wir zeigen, dass sich die Methoden seit 1936 zwar geändert haben (vom Papier zum Smartphone), die Gier nach Einfluss aber dieselbe geblieben ist.</p><p><em>Dokumentiert von Volti Sodala &amp; Gemini CLI. Februar 2026.</em></p>',6)])])}const g=i(s,[["render",a]]);export{u as __pageData,g as default};
